insert into tico_etapas (clave, orden, nombre, apodo, intro, dato, lat, lon) values ('gua', 1, 'Guanacaste', 'Tierra de sabaneros', 'El viaje arranca en el norte seco, entre sabanas doradas, árboles de guanacaste y volcanes humeantes.', 'Guanacaste se anexó a Costa Rica por voluntad de sus pueblos el 25 de julio de 1824.', 10.63, -85.44) on conflict (clave) do update set orden=excluded.orden, nombre=excluded.nombre, apodo=excluded.apodo, intro=excluded.intro, dato=excluded.dato, lat=excluded.lat, lon=excluded.lon;
insert into tico_etapas (clave, orden, nombre, apodo, intro, dato, lat, lon) values ('pun', 2, 'Puntarenas', 'La provincia más grande', 'Bajas hacia el Pacífico: nubes, mar abierto, selva espesa y la isla más lejana del país.', 'Puntarenas es la provincia más extensa de Costa Rica y tiene la isla del Coco, a unos 550 km de la costa.', 9.98, -84.83) on conflict (clave) do update set orden=excluded.orden, nombre=excluded.nombre, apodo=excluded.apodo, intro=excluded.intro, dato=excluded.dato, lat=excluded.lat, lon=excluded.lon;
insert into tico_etapas (clave, orden, nombre, apodo, intro, dato, lat, lon) values ('ala', 3, 'Alajuela', 'Ciudad de los Mangos', 'Subes al Valle Central: cafetales, volcanes, la cuna de Juan Santamaría y las carretas pintadas de Sarchí.', 'En Alajuela nació Juan Santamaría, héroe nacional de la Campaña de 1856.', 10.02, -84.21) on conflict (clave) do update set orden=excluded.orden, nombre=excluded.nombre, apodo=excluded.apodo, intro=excluded.intro, dato=excluded.dato, lat=excluded.lat, lon=excluded.lon;
insert into tico_etapas (clave, orden, nombre, apodo, intro, dato, lat, lon) values ('her', 4, 'Heredia', 'Ciudad de las Flores', 'Entre cafetales y bosque lluvioso llegas a una de las ciudades coloniales más bellas del país.', 'Heredia conserva El Fortín, una torre de 1876 frente a su plaza principal.', 10.0, -84.12) on conflict (clave) do update set orden=excluded.orden, nombre=excluded.nombre, apodo=excluded.apodo, intro=excluded.intro, dato=excluded.dato, lat=excluded.lat, lon=excluded.lon;
insert into tico_etapas (clave, orden, nombre, apodo, intro, dato, lat, lon) values ('sj', 5, 'San José', 'La capital', 'Entras a la capital: teatros, museos, mercados, universidades y mucho tráfico.', 'San José fue fundada en 1737 y es capital desde 1823.', 9.93, -84.08) on conflict (clave) do update set orden=excluded.orden, nombre=excluded.nombre, apodo=excluded.apodo, intro=excluded.intro, dato=excluded.dato, lat=excluded.lat, lon=excluded.lon;
insert into tico_etapas (clave, orden, nombre, apodo, intro, dato, lat, lon) values ('car', 6, 'Cartago', 'La primera capital', 'Subes hacia la antigua capital colonial, a la sombra del volcán Irazú y de la Virgen de los Ángeles.', 'Cartago fue fundada en 1563 y fue la capital de Costa Rica durante la colonia.', 9.86, -83.92) on conflict (clave) do update set orden=excluded.orden, nombre=excluded.nombre, apodo=excluded.apodo, intro=excluded.intro, dato=excluded.dato, lat=excluded.lat, lon=excluded.lon;
insert into tico_etapas (clave, orden, nombre, apodo, intro, dato, lat, lon) values ('lim', 7, 'Limón', 'El Caribe', 'Bajas por las montañas hasta el Caribe: palmeras, lluvia tibia, calipso y tortugas.', 'El ferrocarril al Caribe se terminó en 1890 y trajo a miles de trabajadores de Jamaica.', 10.0, -83.03) on conflict (clave) do update set orden=excluded.orden, nombre=excluded.nombre, apodo=excluded.apodo, intro=excluded.intro, dato=excluded.dato, lat=excluded.lat, lon=excluded.lon;
insert into tico_preguntas (id, etapa, categoria, dificultad, pregunta, opciones, correcta, explicacion) values (1, 'gua', 'geografía', 1, '¿Cuál es la capital de la provincia de Guanacaste?', '["Santa Cruz", "Cañas", "Nicoya", "Liberia"]'::jsonb, 3, 'Liberia es conocida como la "Ciudad Blanca".') on conflict (id) do update set etapa=excluded.etapa, categoria=excluded.categoria, dificultad=excluded.dificultad, pregunta=excluded.pregunta, opciones=excluded.opciones, correcta=excluded.correcta, explicacion=excluded.explicacion;
