insert into tico_preguntas (id, etapa, categoria, dificultad, pregunta, opciones, correcta, explicacion) values (3, 'gua', 'cultura', 1, '¿Cuál es el baile típico nacional de Costa Rica?', '["El punto guanacasteco", "La cumbia", "El merengue", "El tango"]'::jsonb, 0, 'El punto guanacasteco se baila con trajes típicos en fiestas cívicas y escolares.') on conflict (id) do update set etapa=excluded.etapa, categoria=excluded.categoria, dificultad=excluded.dificultad, pregunta=excluded.pregunta, opciones=excluded.opciones, correcta=excluded.correcta, explicacion=excluded.explicacion;
insert into tico_preguntas (id, etapa, categoria, dificultad, pregunta, opciones, correcta, explicacion) values (4, 'gua', 'naturaleza', 1, '¿Cuál es el árbol nacional de Costa Rica?', '["El cedro", "El roble", "El guanacaste", "La ceiba"]'::jsonb, 2, 'El guanacaste fue declarado árbol nacional en 1959 y da nombre a la provincia.') on conflict (id) do update set etapa=excluded.etapa, categoria=excluded.categoria, dificultad=excluded.dificultad, pregunta=excluded.pregunta, opciones=excluded.opciones, correcta=excluded.correcta, explicacion=excluded.explicacion;
