insert into tico_preguntas (id, etapa, categoria, dificultad, pregunta, opciones, correcta, explicacion) values (9, 'pun', 'naturaleza', 2, '¿Qué isla de Costa Rica, a unos 550 km en el Pacífico, es Patrimonio Mundial y famosa por leyendas de tesoros piratas?', '["Isla Chira", "La isla del Coco", "Isla Caño", "Isla Bolaños"]'::jsonb, 1, 'La isla del Coco es Patrimonio Natural de la Humanidad desde 1997.') on conflict (id) do update set etapa=excluded.etapa, categoria=excluded.categoria, dificultad=excluded.dificultad, pregunta=excluded.pregunta, opciones=excluded.opciones, correcta=excluded.correcta, explicacion=excluded.explicacion;
