-- Travesía Tica: preguntas, retos y textos del juego. Ejecutar completo en el SQL Editor de Supabase (se puede repetir sin duplicar).
create table if not exists tico_etapas (clave text primary key, orden int not null, nombre text not null, apodo text, intro text, dato text, lat double precision, lon double precision);
create table if not exists tico_preguntas (id int primary key, etapa text, categoria text, dificultad int not null default 1, pregunta text not null, opciones jsonb not null, correcta int not null, explicacion text, activa boolean not null default true);
create table if not exists tico_ordenes (id int primary key, titulo text not null, items jsonb not null, activa boolean not null default true);
create table if not exists tico_lugares (id int primary key, etapa text, nombre text not null, pista text, lat double precision not null, lon double precision not null, activa boolean not null default true);
create table if not exists tico_textos (clave text primary key, valor text not null);
alter table tico_etapas enable row level security; alter table tico_preguntas enable row level security; alter table tico_ordenes enable row level security; alter table tico_lugares enable row level security; alter table tico_textos enable row level security;
-- Sin políticas: solo la función de Netlify (clave de servicio) puede leer o escribir.

